mapper.select:
SELECT COUNT(*)
FROM SF_INCIDENT i
WHERE i.INCIDENT_ID = #{selectedId}

mapper.update:
UPDATE SF_INCIDENT
SET STATUS = #{newStatus}, UPDATED_AT = SYSTIMESTAMP
WHERE INCIDENT_ID = #{incidentId}
  AND STATUS = #{currentStatus}

UPDATE SF_INCIDENT
SET STATUS = 'CLOSED', CLOSE_REASON = #{closeReason}, UPDATED_AT = SYSTIMESTAMP
WHERE INCIDENT_ID = #{incidentId}
  AND STATUS = #{currentStatus}

mapper.select:
SELECT * FROM SF_INCIDENT_LOG
WHERE INCIDENT_ID = #{incidentId}
ORDER BY CHANGED_AT ASC

SELECT TO_CHAR(CREATED_AT, 'YYYY-MM-DD') AS STAT_DATE, COUNT(*) AS CNT
FROM SF_INCIDENT
WHERE CREATED_AT >= #{fromStart}
  AND CREATED_AT < #{toEnd}
GROUP BY TO_CHAR(CREATED_AT, 'YYYY-MM-DD')

SELECT TO_CHAR(CHANGED_AT, 'YYYY-MM-DD') AS STAT_DATE, COUNT(*) AS CNT
FROM SF_INCIDENT_LOG
WHERE NEW_STATUS = 'CLOSED'
  AND CHANGED_AT >= #{fromStart}
  AND CHANGED_AT < #{toEnd}
GROUP BY TO_CHAR(CHANGED_AT, 'YYYY-MM-DD')

SELECT PHOTO_URL FROM SF_INCIDENT_PHOTO
WHERE INCIDENT_ID = #{incidentId}
ORDER BY SORT_ORDER
